"""Public county guides (guides/, root-only, generated by scripts/build_public_guides.py).

Pins: the generated pages and the sitemap section are current; every internal /guides/ link resolves to a
generated file; pages carry the SEO head, are script-free (JSON-LD data blocks only) and well-formed; only
VERIFIED answers carry an official link; no property data appears; non-Florida pages never say "Lands
Available"; Louisiana uses "Parish"; nothing noindexes /guides/.
"""
from __future__ import annotations

import json
import re
import subprocess
import sys
from html.parser import HTMLParser
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
GUIDES = REPO / "guides"
VOID = {"meta", "link", "br", "img", "input", "hr"}


def run(*args):
    return subprocess.run([sys.executable, str(REPO / "scripts/build_public_guides.py"), *args],
                          capture_output=True, text=True, cwd=REPO)


def pages():
    return sorted(GUIDES.rglob("*.html"))


def target(href: str) -> Path:
    path = href.split("#")[0]
    if path.endswith("/"):
        return REPO / path.lstrip("/") / "index.html"
    if path.endswith((".css", ".html")):
        return REPO / path.lstrip("/")
    return REPO / (path.lstrip("/") + ".html")


class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack, self.errors, self.hrefs, self.scripts, self.ext_links = [], [], [], [], []

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "script":
            self.scripts.append(a.get("type"))
        if tag in ("a", "link") and a.get("href"):
            self.hrefs.append(a["href"])
            if tag == "a" and a["href"].startswith("http"):
                self.ext_links.append(a)
        if tag not in VOID:
            self.stack.append(tag)

    def handle_endtag(self, tag):
        if tag in VOID:
            return
        if not self.stack or self.stack[-1] != tag:
            self.errors.append(f"unexpected </{tag}> (open: {self.stack[-3:]})")
        else:
            self.stack.pop()


def test_outputs_are_current():
    r = run("--check")
    assert r.returncode == 0, r.stdout + r.stderr


def test_page_counts_follow_the_guide_data():
    doc = json.loads((REPO / "public/buyers-guide.json").read_text(encoding="utf-8"))
    assert (GUIDES / "index.html").exists() and (GUIDES / "guides.css").exists()
    for st, state in doc["states"].items():
        assert (GUIDES / st.lower() / "index.html").exists(), st
        with_verified = [c for c, cd in state.get("counties", {}).items()
                         if any(a.get("status") == "VERIFIED" for L in cd.values() for a in L.get("answers", []))]
        assert len(list((GUIDES / st.lower()).glob("*.html"))) == len(with_verified) + 1, st


def test_pages_are_well_formed_script_free_and_links_resolve():
    for p in pages():
        text = p.read_text(encoding="utf-8")
        c = Checker()
        c.feed(text)
        assert not c.errors and c.stack == [], (p, c.errors, c.stack)
        assert set(c.scripts) <= {"application/ld+json"}, p
        for href in c.hrefs:
            if href.startswith("/guides/"):
                assert target(href).exists(), (p, href)
            elif href.startswith("/") and not href.startswith("//"):
                assert (REPO / href.lstrip("/").split("?")[0]).exists(), (p, href)
        for a in c.ext_links:
            if "fonts.googleapis.com" in a["href"]:
                continue
            assert a["href"].startswith("https://") and "noopener" in (a.get("rel") or ""), (p, a)
        for m in re.findall(r'<script type="application/ld\+json">(.*?)</script>', text, re.S):
            json.loads(m)
        for needle in ("<title>", 'name="description"', 'rel="canonical" href="https://taxacq.com/guides/',
                       'property="og:title"', '"BreadcrumbList"'):
            assert needle in text, (p, needle)
        assert "noindex" not in text, p


def test_only_verified_answers_carry_links_and_no_property_data():
    for p in pages():
        text = p.read_text(encoding="utf-8")
        n_answers = text.count('<article class="g-answer">')
        assert text.count("Source: <a href=\"https://") == n_answers, p
        assert n_answers == text.count("· verified 20"), p
        open_list = re.findall(r'<ul class="g-open">(.*?)</ul>', text, re.S)
        assert all("href" not in block for block in open_list), p
        assert not re.search(r"parcel id|owner name|min_bid|case_no", text, re.I), p


def test_unit_words_and_ledger_names():
    la = list((GUIDES / "la").glob("*.html"))
    assert any("Parish, LA" in p.read_text(encoding="utf-8") for p in la)
    for p in pages():
        if "/guides/fl/" not in str(p).replace("\\", "/") and p != GUIDES / "index.html":
            assert "Lands Available" not in p.read_text(encoding="utf-8"), p
    assert "How to buy tax-sale property in Alachua County, FL — TAXACQ" in \
        (GUIDES / "fl/alachua.html").read_text(encoding="utf-8")


def test_sitemap_lists_every_guide_and_nothing_noindexes_them():
    sitemap = (REPO / "sitemap.xml").read_text(encoding="utf-8")
    locs = re.findall(r"<loc>([^<]+)</loc>", sitemap)
    assert len(locs) == len(set(locs))
    guide_locs = [u for u in locs if "/guides/" in u]
    assert len(guide_locs) == len(pages())
    for u in guide_locs:
        assert target(u.removeprefix("https://taxacq.com")).exists(), u
    robots = (REPO / "robots.txt").read_text(encoding="utf-8")
    assert not re.search(r"^Disallow:\s*/guides", robots, re.M)
    for headers in (REPO / "_headers", REPO / "public/_headers"):
        assert not re.search(r"^/guides", headers.read_text(encoding="utf-8"), re.M)
    assert not (REPO / "public/guides").exists()          # root-only, never mirrored


def test_landing_links_the_guides():
    for f in (REPO / "public/index.html", REPO / "index.html"):
        assert '<a href="/guides/">Free county guides</a>' in f.read_text(encoding="utf-8")
